// HasSurface applies the HasEdge predicate on the "surface" edge.
func HasSurface() predicate.WorkPane {
	return predicate.WorkPane(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SurfaceTable, SurfaceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSurfaceWith applies the HasEdge predicate on the "surface" edge with a given conditions (other predicates).
func HasSurfaceWith(preds ...predicate.WorkSurface) predicate.WorkPane {
	return predicate.WorkPane(func(s *sql.Selector) {
		step := newSurfaceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

