// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkPane) predicate.WorkPane {
	return predicate.WorkPane(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkPane) predicate.WorkPane {
	return predicate.WorkPane(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkPane) predicate.WorkPane {
	return predicate.WorkPane(sql.NotPredicates(p))
}
